<?php $e = fn ($v) => App\Core\View::e((string) $v); $value = fn ($key, $default = '') => $e($record[$key] ?? $default); ?>
<div class="section-heading"><div><p class="eyebrow">Vai e Vem</p><h1><?= $editing ? 'Editar movimentação' : 'Nova movimentação' ?></h1></div></div>
<?php foreach (($errors ?? []) as $error): ?><p class="flash-error"><?= $e($error) ?></p><?php endforeach; ?>
<form class="form-grid" method="post" action="<?= $e(App\Core\Config::url($editing ? '/admin/vai-e-vem/' . $record['id'] : '/admin/vai-e-vem')) ?>"><input type="hidden" name="_csrf" value="<?= $e(App\Core\Security::csrfToken()) ?>"><label>Campeonato <select name="championship_id" required><?php foreach ($championships as $c): ?><option value="<?= (int) $c['id'] ?>" <?= (string) ($record['championship_id'] ?? '') === (string) $c['id'] ? 'selected' : '' ?>><?= $e($c['name']) ?></option><?php endforeach; ?></select></label><label>Atleta <select name="athlete_id" required><option value="">Selecione</option><?php foreach ($athletes as $a): ?><option value="<?= (int) $a['id'] ?>" <?= (string) ($record['athlete_id'] ?? '') === (string) $a['id'] ? 'selected' : '' ?>><?= $e($a['sporting_name'] ?: $a['full_name']) ?> - <?= $e($a['team_name']) ?></option><?php endforeach; ?></select></label><label>Equipe anterior <select name="previous_team_id"><option value="">Nenhuma</option><?php foreach ($teams as $team): ?><option value="<?= (int) $team['id'] ?>" <?= (string) ($record['previous_team_id'] ?? '') === (string) $team['id'] ? 'selected' : '' ?>><?= $e($team['name']) ?></option><?php endforeach; ?></select></label><label>Nova equipe <select name="new_team_id"><option value="">Nenhuma</option><?php foreach ($teams as $team): ?><option value="<?= (int) $team['id'] ?>" <?= (string) ($record['new_team_id'] ?? '') === (string) $team['id'] ? 'selected' : '' ?>><?= $e($team['name']) ?></option><?php endforeach; ?></select></label><?php if ($requestOnly ?? false): ?><label>Tipo <input type="text" value="transferencia" disabled><input type="hidden" name="type" value="transferencia"></label><?php else: ?><label>Tipo <select name="type" required><?php foreach ($types as $type): ?><option value="<?= $e($type) ?>" <?= ($record['type'] ?? '') === $type ? 'selected' : '' ?>><?= $e($type) ?></option><?php endforeach; ?></select></label><?php endif; ?><label>Data <input type="date" name="movement_date" value="<?= $value('movement_date') ?>" required></label><label class="full-width">Observação publica <textarea name="public_observation" rows="4"><?= $value('public_observation') ?></textarea></label><label class="full-width">Notas internas <textarea name="internal_notes" rows="4"><?= $value('internal_notes') ?></textarea></label><label>Status <select name="status"><option value="draft" <?= ($record['status'] ?? 'draft') === 'draft' ? 'selected' : '' ?>>draft</option><option value="pending" <?= ($record['status'] ?? '') === 'pending' ? 'selected' : '' ?>>pending</option></select></label><div><button type="submit">Salvar</button></div></form>
